import {Icon, IndexPath} from '@ui-kitten/components';
import React, {useState} from 'react';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import DropdownListCM from '../../../../components/DropDownList';
import {useTranslation} from 'react-i18next';
import {Color, Font} from '../../../../../constants';
import TextCM from '../../../../components/Text';
import {listStatusFromERequest, listType} from './helper';
import Toast from 'react-native-toast-message';
import InputDate from '../../../../screen/my-receipt/component/modal-filter/InputDate';
import {ValueFilterSearch} from '../zustand/store';
import {useAccountInfoServices} from '../../../../../hooks/apiHooks/useAccountInfoServices';
import {useConfigStore} from '../../../zustand/config';
type Props = {
  onClose: () => void;
  handleSubmitFilter?: () => void;
  setValueFilterSearch: React.Dispatch<
    React.SetStateAction<ValueFilterSearch | undefined>
  >;
  valueFilterSearch?: ValueFilterSearch;
  type: 'owner' | 'authorized';
};
const ModalFilter = ({
  handleSubmitFilter,
  setValueFilterSearch,
  valueFilterSearch,
  onClose,
  type,
}: Props) => {
  const {t} = useTranslation();
  const [valueFilterSearchState, setValueFilterSearchState] = useState<
    ValueFilterSearch | undefined
  >(valueFilterSearch);

  const {LIST_ORG} = useConfigStore();

  const AccountService = useAccountInfoServices();

  const onChangeStartDate = (value: string | null) => {
    const newStart = value ? new Date(value) : undefined;
    const {endDate} = valueFilterSearch?.rangeDay ?? {};
    if (endDate && newStart && newStart > endDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('BLDT.start_date_not_greater_than_end_date'),
      });
      return;
    }

    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {
        ...valueFilterSearchState?.rangeDay,
        startDate: newStart,
      },
    });
  };
  const onChangeEndDate = (value: string | null) => {
    // const today = new Date();
    // today.setHours(0, 0, 0, 0);
    const newEnd = value ? new Date(value) : undefined;
    // if (newEnd && newEnd > today) {
    //   Toast.show({
    //     type: 'error',
    //     text1: t('CM.noti'),
    //     text2: 'Ngày kết thúc không được lớn hơn ngày hôm nay.',
    //   });
    //   return;
    // }
    const {startDate} = valueFilterSearchState?.rangeDay ?? {};
    if (startDate && newEnd && newEnd < startDate) {
      Toast.show({
        type: 'error',
        text1: t('CM.not'),
        text2: t('BLDT.end_date_not_less_than_start_date'),
      });
      return;
    }
    setValueFilterSearchState({
      ...valueFilterSearchState,
      rangeDay: {...valueFilterSearchState?.rangeDay, endDate: newEnd},
    });
  };

  const handleClear = () => {
    setValueFilterSearchState(undefined);
  };

  const handleSubmit = () => {
    setValueFilterSearch(valueFilterSearchState);
    handleSubmitFilter?.();
  };

  const handleGetUser = async (paramsProps?: any, textSearch?: string) => {
    try {
      const params = {
        ...paramsProps,
      };
      const dataFilter = {
        q: textSearch,
      };
      const data = await AccountService.getListAccount(dataFilter, params);
      return data;
    } catch (error) {}
  };

  return (
    <View>
      <ScrollView>
        <View style={{marginVertical: 4}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('Nguồn nhận')}
          </TextCM>
          <DropdownListCM
            onSelect={(item: IndexPath[]) => {
              setValueFilterSearchState({
                ...valueFilterSearchState,
                type: item,
              });
            }}
            valueSelect={valueFilterSearchState?.type}
            placeholder={t('Chọn nguồn nhận')}
            multiple={true}
            listData={listType}
          />
        </View>
        <View style={{marginVertical: 4}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('Trạng thái hợp đồng')}
          </TextCM>
          <DropdownListCM
            onSelect={(item: IndexPath[]) => {
              setValueFilterSearchState({
                ...valueFilterSearchState,
                status: item,
              });
            }}
            valueSelect={valueFilterSearchState?.status}
            placeholder={t('Chọn trạng thái hợp đồng')}
            multiple={true}
            listData={listStatusFromERequest}
            isi18n={true}
          />
        </View>
        {type === 'authorized' && (
          <View style={{marginVertical: 4}}>
            <TextCM
              style={{
                marginVertical: 8,
                fontFamily: Font.InterMedium500,
                fontSize: 14,
              }}>
              {t('Tổ chức')}
            </TextCM>

            <DropdownListCM
              onSelect={(item: IndexPath) => {
                setValueFilterSearchState({
                  ...valueFilterSearchState,
                  orgIn: item,
                });
              }}
              valueSelect={valueFilterSearchState?.orgIn}
              placeholder={t('Chọn tổ chức')}
              listData={LIST_ORG as any}
            />
          </View>
        )}

        <View style={{marginVertical: 4, marginBottom: 12}}>
          <TextCM
            style={{
              marginVertical: 8,
              fontFamily: Font.InterMedium500,
              fontSize: 14,
            }}>
            {t('Ngày tiếp nhận')}
          </TextCM>
          <View
            style={{
              flexDirection: 'row',
              justifyContent: 'space-between',
              alignItems: 'center',
              marginTop: 10,
              columnGap: 8,
            }}>
            <InputDate
              containerStyle={{flex: 1}}
              value={valueFilterSearchState?.rangeDay?.startDate || null}
              onChangeDate={value => {
                onChangeStartDate(value);
              }}
              maxDate={new Date()}
              disabled={false}
            />
            <Icon name="arrow-forward-outline" width={20} height={20} />
            <InputDate
              containerStyle={{flex: 1}}
              value={valueFilterSearchState?.rangeDay?.endDate || null}
              onChangeDate={value => {
                onChangeEndDate(value);
              }}
              maxDate={new Date()}
              disabled={false}
            />
          </View>
        </View>
      </ScrollView>
      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-evenly',
          alignItems: 'center',
          gap: 16,
        }}>
        <TouchableOpacity
          onPress={handleClear}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#E8F5FF',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#055FA4', textAlign: 'center'}}>
            {t('DB.filter.set-default')}
          </TextCM>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={handleSubmit}
          style={{
            flex: 1,
            padding: 12,
            backgroundColor: '#055FA4',
            borderRadius: 8,
          }}>
          <TextCM style={{color: '#fff', textAlign: 'center'}}>
            {t('BLDT.filter')}
          </TextCM>
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ModalFilter;
