import {
  ActivityIndicator,
  RefreshControl,
  ScrollView,
  View,
} from 'react-native';
import HeaderCM from '../../components/Header/HeaderCM';
import {styles} from './styles';
import {
  IconCalendarLabel,
  IconIdReceipt,
  IconLabelKey,
  IconLabelReceiptStatus,
  IconPersonlabel,
} from '../../../assets/images';
import {listActionNext, statusRequestTagProperties} from './helper';
import BottomItem from './component/bottom-item';
import DetailItem from './component/detail-item';
import {useEffect, useState} from 'react';
import {useRoute} from '@react-navigation/native';
import {useReceiptServices} from '../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {DateUtils} from '../../../utils';
import {Color} from '../../../constants';
import {DetailReceipt} from '../../../model/interface/receipt.interface';
import {useAccountInfoServices} from '../../../hooks/apiHooks/useAccountInfoServices';
import {IUserInfo} from '../../../model/interface/service.interface';
import {
  listRequestStatus,
  listStatusReceipt,
} from '../my-receipt/component/modal-filter/helper';
import TextCM from '../../components/Text';

const DetailReceiptScreen = () => {
  const ReceiptService = useReceiptServices();
  const AccountService = useAccountInfoServices();
  const {t} = useTranslation();
  const router = useRoute<any>();
  const {id} = router.params;

  const [dataDetailReceipt, setDetailReceipt] = useState<DetailReceipt>(
    {} as DetailReceipt,
  );
  const [createByDetail, setCreateByDetail] = useState<IUserInfo>();
  const [isLoading, setIsLoading] = useState(false);
  const [refreshing, setRefresing] = useState(false);

  const getDataDetail = async (isLoading: boolean) => {
    if (isLoading) {
      setIsLoading(true);
    } else {
      setRefresing(true);
    }
    try {
      const res = (await ReceiptService.getReceiptById(id)) as DetailReceipt;
      if (res) {
        setDetailReceipt(res);
        const filter = {
          logins: [res.createdBy],
        };
        const resCreateBy = await AccountService.getListAccount(filter);
        setCreateByDetail(resCreateBy?.data[0]);
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsLoading(false);
      setRefresing(false);
    }
  };
  useEffect(() => {
    getDataDetail(true);
  }, [id]);

  const StatusTag = ({
    status,
    type,
  }: {
    status: string;
    type: 'DEFAULT' | 'REQUEST' | 'MIX';
  }) => {
    let properties;
    if (type === 'DEFAULT') {
      properties = listStatusReceipt.find((item: any) => item.value === status);
    } else if (type === 'REQUEST') {
      properties = statusRequestTagProperties.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    } else {
      properties = listRequestStatus.find(
        (item: any) => item?.value?.toLowerCase() === status,
      );
    }
    if (properties) {
      return (
        <View style={{flex: 1, flexDirection: 'row'}}>
          <View
            style={[
              styles.statusTag,
              {backgroundColor: properties?.bgColor || '#EF5DA81A'},
            ]}>
            <TextCM
              style={[
                styles.statusText,
                {color: properties?.color || '#d94936'},
              ]}>
              {t(`BLDT.${properties?.value}`)}
            </TextCM>
          </View>
          <View style={{flex: 1}} />
        </View>
      );
    }
    return (
      <View style={{flexDirection: 'row', flex: 1}}>
        <View style={[styles.statusTag, {backgroundColor: '#EF5DA81A'}]}>
          <TextCM style={[styles.statusText, {color: '#d94936'}]}>
            {t(`BLDT.${status}`)}
          </TextCM>
        </View>
        <View style={{flex: 1}} />
      </View>
    );
  };

  const onRefresh = () => {
    setRefresing(true);
    getDataDetail(false);
  };

  return (
    <>
      <HeaderCM title={t('BLDT.receipt_detail')} />
      {isLoading ? (
        <View style={{flex: 1, justifyContent: 'center', alignItems: 'center'}}>
          <ActivityIndicator color={Color.BgPrimary} size={'large'} />
        </View>
      ) : (
        <ScrollView
          refreshControl={
            <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
          }
          style={styles.content}>
          <View style={styles.titleSection}>
            <TextCM style={styles.titleText}>
              {dataDetailReceipt?.name || '---'}
            </TextCM>
            <TextCM style={styles.idText}>
              {dataDetailReceipt?.attrs?.caseCode || '---'}
            </TextCM>
          </View>

          <View style={styles.detailsSection}>
            <DetailItem
              icon={<IconIdReceipt width={16} height={16} />}
              label={t('BLDT.search_code')}
              value={dataDetailReceipt?.lookUp || '---'}
            />

            <DetailItem
              icon={<IconIdReceipt width={16} height={16} />}
              label={t('BLDT.verdict_code')}
              value={dataDetailReceipt?.code || '---'}
            />

            <DetailItem
              icon={<IconCalendarLabel width={16} height={16} />}
              label={t('CM.createDateCard')}
              value={DateUtils.convertDateToDDMMYYYY_H_M(
                dataDetailReceipt?.createdDate,
              )}
            />

            <DetailItem
              icon={<IconPersonlabel width={16} height={16} />}
              label={t('CM.createdBy')}
              isUser={true}
              value={{
                name: createByDetail && createByDetail.personalName,
                email: createByDetail && createByDetail?.email,
                avatar: createByDetail && createByDetail?.imageUrl,
              }}
            />

            <DetailItem
              icon={<IconLabelReceiptStatus width={16} height={16} />}
              label={t('BLDT.flow_status')}
              value={
                <StatusTag
                  status={dataDetailReceipt?.flowStatus}
                  type="REQUEST"
                />
              }
            />

            <DetailItem
              icon={<IconLabelKey width={16} height={16} />}
              label={t('BLDT.receipt_status')}
              value={
                <StatusTag status={dataDetailReceipt?.status} type="DEFAULT" />
              }
            />

            <DetailItem
              icon={<IconLabelKey width={16} height={16} />}
              label={t('BLDT.funding_status')}
              value={
                <StatusTag
                  status={dataDetailReceipt?.requestStatus}
                  type="MIX"
                />
              }
            />

            <View style={styles.bottomMenu}>
              {listActionNext.map(item => {
                return (
                  <BottomItem
                    key={item.key}
                    action={item.key}
                    icon={item.icon}
                    label={item.label}
                    id={id}
                    dataDetailReceipt={dataDetailReceipt}
                  />
                );
              })}
            </View>
          </View>
        </ScrollView>
      )}
    </>
  );
};

export default DetailReceiptScreen;
