import {StyleSheet, TouchableOpacity, View} from 'react-native';
import {Color, Font} from '../../../../../../../constants';
import Profile from '../../../../../../components/Profile';
import {CommonUtils, DateUtils} from '../../../../../../../utils';
import {useEffect, useState} from 'react';
import {IReceiptAttach} from '../../../../../../../model/interface/receipt.interface';
import {useUserZustandStore} from '../../../../../../../zutand/UserZustandStore';
import {IUserInfo} from '../../../../../../../model/interface/service.interface';
import TextCM from '../../../../../../components/Text';
import {useNavigation} from '@react-navigation/native';
import {useTranslation} from 'react-i18next';

type Props = {
  item: IReceiptAttach;
};
const ExpandAttachment = ({item}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const {listCurrentUserInfo} = useUserZustandStore();
  const [userInfo, setUserInfo] = useState<IUserInfo>();
  const openAttach = () => {
    navigation.navigate('ViewDocumentScreen', {
      item: item,
    });
  };

  useEffect(() => {
    const userInfoFind = listCurrentUserInfo.find(
      user => user.email === item.createdBy,
    );
    if (userInfoFind) {
      setUserInfo(userInfoFind);
    }
  }, []);
  const getType = (fileName: string) => {
    const typeFile = fileName.split('.');
    return `.${typeFile[typeFile.length - 1]}`;
  };

  return (
    <View style={styles.expandedDetails}>
      {/* <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>Loại tài liệu</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {item?.type ? item.type : getType(item?.fileName)}
          </TextCM>
        </View>
      </View> */}

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('CM.attachment_')}</TextCM>
        <TouchableOpacity style={{flex: 1}} onPress={openAttach}>
          <TextCM
            style={[
              styles.detailValue,
              {textDecorationLine: 'underline', color: '#366AE2'},
            ]}>
            {item.fileName || ' ---'}
          </TextCM>
        </TouchableOpacity>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('CM.format')}</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {getType(item?.fileName) || '---'}
          </TextCM>
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('CM.size')}</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {item.size ? CommonUtils.getSize(item.size) : '---'}
          </TextCM>
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('BLDT.step')}</TextCM>
        <View style={{flex: 1}}>
          {item?.notionName ? (
            <TextCM style={styles.detailValue}>{item.notionName}</TextCM>
          ) : (
            <TextCM style={styles.detailValue}>{'---'}</TextCM>
          )}
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('BLDT.uploader')}</TextCM>
        <View style={styles.userInfo}>
          {item.createdBy ? (
            userInfo && (
              <Profile
                avatar={userInfo?.imageUrl}
                name={userInfo.personalName || '---'}
                email={item.createdBy || '---'}
              />
            )
          ) : (
            <TextCM style={styles.detailValue}>N/A</TextCM>
          )}
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>{t('BLDT.upload_time')}</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {DateUtils.convertDateToDDMMYYYY_H_M(item.createdDate)}
          </TextCM>
        </View>
      </View>
    </View>
  );
};
export default ExpandAttachment;

const styles = StyleSheet.create({
  expandedDetails: {
    backgroundColor: '#FFFFFF',
    borderRadius: 6,
    padding: 12,
    marginVertical: 8,
  },
  detailRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
    columnGap: 12,
  },
  detailLabel: {
    fontSize: 12,
    fontFamily: Font.InterSemiBold600,
    color: '#00204D',
    width: 115,
  },
  detailValue: {
    fontSize: 12,
    fontFamily: Font.InterRegular400,
    color: '#00204DE5',
  },
  userInfo: {
    flexDirection: 'row',
    alignItems: 'center',
    flex: 1
  },
  avatar: {
    width: 24,
    height: 24,
    borderRadius: 12,
    marginRight: 8,
  },
  email: {
    fontSize: 12,
    color: '#6B7280',
  },
});
