import {Image, useWindowDimensions, View} from 'react-native';
import {styles} from './styles';
import {String} from '../../../../../constants';
import TextCM from '../../../../components/Text';

type ProppsDetailItem = {
  icon: React.ReactElement;
  label: string;
  value?: any;
  isUser?: boolean;
};

const DetailItem = ({icon, label, value, isUser = false}: ProppsDetailItem) => {
  const {width} = useWindowDimensions();
  const UserAvatar = ({
    name,
    email,
    avatar,
  }: {
    name: string;
    email: string;
    avatar?: string;
  }) => (
    <View style={styles.avatarContainer}>
      <Image
        source={{
          uri: avatar || String.DEFAULT_IMAGE,
        }}
        style={styles.avatar}
      />
      <View style={styles.avatarTextContainer}>
        <View style={{flex: 1}}>
          <TextCM style={[styles.avatarName, {flex: 1}]}>
            {name || '---'}
          </TextCM>
        </View>
        <View style={{flex: 1}}>
          <TextCM style={styles.avatarEmail}>{email || '---'}</TextCM>
        </View>
      </View>
    </View>
  );
  return (
    <View style={styles.detailItem}>
      <View
        style={[
          styles.detailIconLabel,
          width < 500 ? {minWidth: 140} : {flex: 1},
        ]}>
        {icon}
        <TextCM style={styles.detailLabel}>{label || '---'}</TextCM>
      </View>

      {isUser ? (
        <UserAvatar
          name={value.name}
          email={value.email}
          avatar={value.avatar}
        />
      ) : typeof value === 'string' ? (
        <View style={{flex: 1}}>
          <TextCM selectable={true} style={styles.detailValue}>
            {value || '---'}
          </TextCM>
        </View>
      ) : (
        value
      )}
    </View>
  );
};
export default DetailItem;
