import {create} from 'zustand';
import {IUserInfo} from '../model/interface/service.interface';

interface ZutandStore {
  listCurrentUserInfo: IUserInfo[];
  uniqueUserEmails: Set<string>;
  setListCurrentUserInfo: (listCurrentUserInfo: IUserInfo[]) => void;
  setUniqueUserEmails: (uniqueUserEmails: Set<string>) => void;
}

const initialReceiptState = {
  listCurrentUserInfo: [],
  uniqueUserEmails: new Set<string>(),
};

export const useUserZustandStore = create<ZutandStore>((set, get) => ({
  ...initialReceiptState,
  setListCurrentUserInfo: (listCurrentUserInfo: IUserInfo[]) => {
    set({listCurrentUserInfo});
  },
  setUniqueUserEmails: (uniqueUserEmails: Set<string>) => {
    set({uniqueUserEmails});
  },
}));
